#!/usr/bin/env python3
"""Generated by CodeRig. Do not edit; regenerate with `coderig connect`.

Runs the harness sensors from sensors.json (served by Launchpad).

    python .coderig/verify.py --stop   Claude Code Stop hook: exit 2 returns findings to the agent
    python .coderig/verify.py          run every sensor once and print the result (exit 1 on failure)
        --only ID[,ID]                 run just these sensors, e.g. --only TEST-QUALITY
        --requirement "text"           what the change is for, given to the inferential reviewer
"""
import fnmatch
import hashlib
import json
import os
import shlex
import subprocess
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
CONFIG = json.loads((HERE / "sensors.json").read_text(encoding="utf-8"))
STATE = HERE / "state" / "verify.json"
LOG = HERE / "state" / "runs.jsonl"
START = time.time()
MAX_CHARS = 6000
MAX_LINES = 60
MAX_DIFF_CHARS = 60000
MAX_FILE_CHARS = 20000
MAX_FILES_CHARS = 60000
DEFAULT_TEST_GLOBS = ["*/test/*", "*/tests/*", "*Test.java", "*Tests.java", "test_*.py", "*_test.py",
                      "*.test.*", "*.spec.*"]


# ── computational sensors ────────────────────────────────────────────────────

def command(sensor):
    args = shlex.split(sensor["run"].replace("{root}", str(ROOT)))
    docker = (CONFIG.get("runtime") or {}).get("docker")
    if not docker:
        return args
    wrapped = ["docker", "run", "--rm", "-v", f"{ROOT}:{docker['workdir']}"]
    cache = docker.get("cache")
    if cache:
        wrapped += ["-v", f"{cache['volume']}:{cache['path']}"]
    return wrapped + ["-w", docker["workdir"], docker["image"]] + args


def trim(text):
    """Keep the lines that explain the failure, plus the indented detail under them
    (e.g. the key names listed beneath 'Missing keys in ...'), else the whole output."""
    lines = text.splitlines()
    keep = set()
    for i, line in enumerate(lines):
        if "[ERROR]" in line or "FAIL" in line or "Missing keys" in line:
            keep.add(i)
            j = i + 1
            while j < len(lines) and lines[j][:1] in (" ", "\t") and j - i <= 3:
                keep.add(j)
                j += 1
    chosen = [lines[i] for i in sorted(keep)] if keep else lines
    return "\n".join(chosen[-MAX_LINES:])[-MAX_CHARS:]


def run_sensor(sensor):
    """Returns (status, output): status is ok | failed | error. `error` means the check
    could not run (no Docker, timeout); the agent cannot fix that, so it is not fed back."""
    try:
        done = subprocess.run(
            command(sensor), cwd=ROOT, capture_output=True, text=True,
            encoding="utf-8", errors="replace", timeout=sensor.get("timeout_sec", 600),
        )
    except FileNotFoundError as exc:
        return "error", f"cannot run: {exc}"
    except subprocess.TimeoutExpired:
        return "error", f"timed out after {sensor.get('timeout_sec', 600)}s"
    output = (done.stdout or "") + (done.stderr or "")
    return ("ok" if done.returncode == 0 else "failed"), trim(output)


# ── inferential sensors (an agent on Launchpad judges the change) ────────────

def git(*args):
    try:
        done = subprocess.run(["git", *args], cwd=ROOT, capture_output=True, text=True,
                              encoding="utf-8", errors="replace")
    except FileNotFoundError:
        return ""
    return done.stdout if done.returncode == 0 else ""


def fingerprint():
    """What the agent has changed that the sensors care about.

    "unknown": not a git repository, so run the sensors to be safe.
    "clean":   nothing changed apart from CodeRig's own files (a plan-only or question-only turn).
    otherwise: a hash of the changed paths and their sizes and times, so an unchanged tree that has
               already passed is not checked again.
    """
    if git("rev-parse", "--is-inside-work-tree").strip() != "true":
        return "unknown"
    ignore = CONFIG.get("ignore_paths", [])
    changed = []
    for line in git("status", "--porcelain", "--untracked-files=all").splitlines():
        path = line[3:].strip().strip('"')
        if " -> " in path:
            path = path.split(" -> ")[-1]
        if any(path == p.rstrip("/") or path.startswith(p) for p in ignore):
            continue
        changed.append(path)
    if not changed:
        return "clean"
    parts = []
    for path in sorted(changed):
        try:
            info = (ROOT / path).stat()
            parts.append(f"{path}:{info.st_size}:{info.st_mtime_ns}")
        except OSError:
            parts.append(f"{path}:deleted")
    return hashlib.sha256("\n".join(parts).encode("utf-8")).hexdigest()


def read_text(path):
    try:
        return (ROOT / path).read_text(encoding="utf-8")[:MAX_FILE_CHARS]
    except (OSError, UnicodeDecodeError):
        return None


def requirement(payload):
    """What the change is for: the developer's first message in this session if the hook gave
    us the transcript, else the latest commit subject. Best effort; the reviewer copes without."""
    if payload.get("requirement"):
        return str(payload["requirement"])[:3000]
    transcript = payload.get("transcript_path")
    if transcript:
        try:
            for line in Path(transcript).read_text(encoding="utf-8").splitlines():
                entry = json.loads(line)
                message = entry.get("message") or {}
                if entry.get("type") != "user" and message.get("role") != "user":
                    continue
                content = message.get("content")
                if isinstance(content, list):
                    content = " ".join(part.get("text", "") for part in content if isinstance(part, dict))
                if isinstance(content, str) and content.strip():
                    return content.strip()[:3000]
        except (OSError, ValueError):
            pass
    return git("log", "-1", "--pretty=%s").strip()


def gather(sensor, payload):
    diff = git("diff", "HEAD") or git("diff")
    names = [n for n in git("diff", "--name-only", "HEAD").splitlines() if n]
    untracked = [n for n in git("ls-files", "--others", "--exclude-standard").splitlines() if n]
    globs = sensor.get("test_globs") or DEFAULT_TEST_GLOBS
    is_test = lambda name: any(fnmatch.fnmatch(name.replace(os.sep, "/"), g) for g in globs)

    new_files, test_files, budget = {}, {}, MAX_FILES_CHARS
    for name in untracked:
        text = read_text(name)
        if text is not None and budget > 0:
            (test_files if is_test(name) else new_files)[name] = text
            budget -= len(text)
    for name in names:
        if is_test(name) and budget > 0:
            text = read_text(name)
            if text is not None:
                test_files[name] = text
                budget -= len(text)
    return {"requirement": requirement(payload), "diff": diff[:MAX_DIFF_CHARS],
            "new_files": new_files, "test_files": test_files}


def format_review(output):
    lines = [output.get("summary", "")]
    for f in output.get("findings", []):
        lines.append(f"- [{f.get('severity', '?')}] {f.get('scenario', '')}: {f.get('why', '')}"
                     f" Suggested test: {f.get('suggested_test', '')}")
    return "\n".join(line for line in lines if line)


def run_review(sensor, payload):
    base = CONFIG.get("launchpad_url")
    token = os.environ.get(CONFIG.get("token_env") or "CODERIG_TOKEN", "")
    if not base:
        return "error", "Launchpad URL unknown; run `coderig connect` against Launchpad."
    if not token:
        return "error", f"{CONFIG.get('token_env') or 'CODERIG_TOKEN'} is not set; run `eval \"$(coderig env)\"`."
    url = f"{base.rstrip('/')}/api/v1/registry/agents/{sensor['agent']}/run"
    request = urllib.request.Request(
        url, data=json.dumps({"input": gather(sensor, payload)}).encode("utf-8"), method="POST",
        headers={"Content-Type": "application/json", "Authorization": f"Bearer {token}"})
    try:
        with urllib.request.urlopen(request, timeout=sensor.get("timeout_sec", 150)) as response:
            result = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")[:300]
        return "error", f"Launchpad answered {exc.code}: {detail}"
    except (urllib.error.URLError, OSError, ValueError) as exc:
        return "error", f"could not reach Launchpad: {exc}"
    output = result.get("output", {})
    return ("ok" if output.get("verdict") == "pass" else "failed"), format_review(output)


# ── loop ─────────────────────────────────────────────────────────────────────

def load_state():
    try:
        return json.loads(STATE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def save_state(state):
    STATE.parent.mkdir(parents=True, exist_ok=True)
    STATE.write_text(json.dumps(state), encoding="utf-8")


def timed(sensor, runner, *args):
    started = time.time()
    status, output = runner(sensor, *args)
    return {"sensor": sensor, "status": status, "output": output, "seconds": round(time.time() - started, 1)}


def log_run(session, outcome, results, attempt=None):
    """One JSON line per stop in .coderig/state/runs.jsonl: what ran, what it said, how long it took.
    A passing review is silent in the agent's session, so this is how a developer (and the
    measurement of the harness itself) sees what the sensors actually did."""
    record = {
        "time": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "session": session,
        "outcome": outcome,
        "seconds": round(time.time() - START, 1),
        "sensors": [{
            "id": r["sensor"]["id"],
            "kind": r["sensor"].get("kind", "computational"),
            "status": r["status"],
            "seconds": r["seconds"],
            "detail": r["output"][:800] if (r["status"] != "ok" or r["sensor"].get("kind") == "inferential") else "",
        } for r in results],
    }
    if attempt is not None:
        record["attempt"] = attempt
    try:
        LOG.parent.mkdir(parents=True, exist_ok=True)
        if LOG.exists() and LOG.stat().st_size > 1_000_000:
            LOG.replace(LOG.with_suffix(".jsonl.1"))
        with LOG.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(record, ensure_ascii=False) + "\n")
    except OSError:
        pass                                    # logging must never break the hook


def computational():
    return [s for s in CONFIG["sensors"] if s.get("kind", "computational") == "computational"]


def inferential():
    return [s for s in CONFIG["sensors"] if s.get("kind") == "inferential"]


def report(results):
    lines = []
    for r in results:
        s = r["sensor"]
        if r["status"] == "ok":
            continue
        label = "FAILED" if r["status"] == "failed" else "COULD NOT RUN"
        lines.append(f"[{s['id']}] {s.get('title', '')} - {label}")
        lines.append(r["output"] or "(no output)")
        if r["status"] == "failed" and s.get("feedback"):
            lines.append("How to fix: " + " ".join(s["feedback"].split()))
        lines.append("")
    return "\n".join(lines).rstrip()


def blocking_failures(results):
    return [r for r in results if r["status"] == "failed" and r["sensor"].get("blocking", True)]


def hook():
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        payload = {}
    session = str(payload.get("session_id", "default"))
    limit = CONFIG.get("loop", {}).get("max_iterations", 3)
    state = load_state()
    entry = state.get(session) or {"attempts": 0, "runs": {}}

    # Nothing to check: the agent only asked a question or wrote a plan, or this exact change
    # already passed. Skipping saves minutes of build on every turn that did not touch the code.
    print_fp = fingerprint()
    if print_fp == "clean":
        state.pop(session, None)
        save_state(state)
        log_run(session, "skipped-clean", [])
        return 0
    if print_fp != "unknown" and entry.get("passed") == print_fp:
        log_run(session, "skipped-unchanged", [])
        return 0

    results = [timed(s, run_sensor) for s in computational()]
    failed = blocking_failures(results)

    if not failed:
        # The deterministic checks pass, so spend an agent's judgement, once per session.
        for sensor in inferential():
            if entry["runs"].get(sensor["id"], 0) >= (sensor.get("max_runs") or 1):
                continue
            entry["runs"][sensor["id"]] = entry["runs"].get(sensor["id"], 0) + 1
            results.append(timed(sensor, run_review, payload))
        failed = blocking_failures(results)

    broken = [r for r in results if r["status"] == "error"]

    if not failed:
        if print_fp == "unknown":
            state.pop(session, None)
        else:
            # Fingerprint the tree as the sensors left it (a build may write files), so the
            # next stop compares like with like.
            state[session] = {"attempts": 0, "runs": {}, "passed": fingerprint()}
        save_state(state)
        log_run(session, "error" if broken else "pass", results)
        if broken:
            print(json.dumps({"systemMessage": "Harness checks could not run:\n" + report(broken)}))
        return 0

    entry["attempts"] += 1
    if entry["attempts"] > limit:
        state.pop(session, None)
        save_state(state)
        log_run(session, "exhausted", results, attempt=entry["attempts"])
        print(json.dumps({"systemMessage": (
            f"Harness: sensors still failing after {limit} attempts. Stopping so you can decide.\n"
            + report(failed))}))
        return 0

    state[session] = entry
    save_state(state)
    log_run(session, "feedback", results, attempt=entry["attempts"])
    sys.stderr.write(
        f"HARNESS FEEDBACK (attempt {entry['attempts']} of {limit}). Fix these, then finish again; "
        f"the checks re-run automatically.\n\n" + report(failed) + "\n")
    return 2


def option(name):
    if name in sys.argv:
        position = sys.argv.index(name)
        return sys.argv[position + 1] if position + 1 < len(sys.argv) else None
    return None


def main():
    if "--stop" in sys.argv:
        return hook()
    only = option("--only")
    wanted = set(only.split(",")) if only else None
    payload = {"requirement": option("--requirement") or ""}
    results = [timed(s, run_sensor) for s in computational() if wanted is None or s["id"] in wanted]
    if not blocking_failures(results):
        results += [timed(s, run_review, payload) for s in inferential() if wanted is None or s["id"] in wanted]
    for r in results:
        print(f"{r['sensor']['id']:<14} {r['status']:<7} {r['seconds']}s")
    text = report(results)
    if text:
        print("\n" + text)
    return 0 if all(r["status"] == "ok" for r in results) else 1


if __name__ == "__main__":
    sys.exit(main())
